PRAGMA foreign_keys = OFF;

CREATE TABLE IF NOT EXISTS "settings" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"cara_pembayaran" TEXT,"created_at" TEXT,"updated_at" TEXT,"deleted_at" TEXT);
CREATE TABLE IF NOT EXISTS "sys_settings_m" ("smtp_host" TEXT NOT NULL DEFAULT '',"smtp_port" TEXT NOT NULL,"smtp_username" TEXT NOT NULL DEFAULT '',"smtp_password" TEXT NOT NULL DEFAULT '',"smtp_secure" TEXT,"show_pertanyaan" TEXT NOT NULL DEFAULT 'yes',"show_youtube" TEXT NOT NULL DEFAULT 'yes',"mdb" INTEGER,"mdd" TEXT);
CREATE TABLE IF NOT EXISTS "tbl_ads" ("ads_id" INTEGER PRIMARY KEY AUTOINCREMENT,"ads_position" INTEGER NOT NULL,"ads_type" INTEGER NOT NULL,"ads_file_type" INTEGER NOT NULL,"ads_url" TEXT NOT NULL,"ads_link" TEXT NOT NULL,"ads_status" INTEGER NOT NULL,"ads_created_date" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "tbl_ads_pop" ("ads_id" INTEGER PRIMARY KEY AUTOINCREMENT,"ads_position" INTEGER NOT NULL,"ads_type" INTEGER NOT NULL,"ads_file_type" INTEGER NOT NULL,"ads_url" TEXT NOT NULL,"ads_link" TEXT NOT NULL,"ads_content" TEXT,"ads_status" TEXT NOT NULL,"ads_created_date" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "tbl_article" ("article_id" INTEGER PRIMARY KEY AUTOINCREMENT,"headline_news" INTEGER NOT NULL DEFAULT 0,"label_id" INTEGER NOT NULL DEFAULT 0,"article_date" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,"article_uri" TEXT NOT NULL,"article_title" TEXT NOT NULL,"article_author" TEXT NOT NULL,"article_content" TEXT NOT NULL,"article_img" TEXT,"article_pdf" TEXT,"article_status" INTEGER NOT NULL,"article_views" INTEGER NOT NULL,"article_created_by" INTEGER NOT NULL,"article_created_date" TEXT DEFAULT CURRENT_TIMESTAMP,"create_date" TEXT);
CREATE TABLE IF NOT EXISTS "tbl_article_category" ("article_id" INTEGER NOT NULL,"category_id" INTEGER NOT NULL,"sub_category_id" INTEGER NOT NULL,"created_date" TEXT,PRIMARY KEY ("article_id", "category_id", "sub_category_id"));
CREATE TABLE IF NOT EXISTS "tbl_banner" ("id_banner" INTEGER PRIMARY KEY AUTOINCREMENT,"nama_banner" TEXT,"file_banner" TEXT,"link_url" TEXT,"status" TEXT DEFAULT 'yes',"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_category" ("category_id" INTEGER PRIMARY KEY AUTOINCREMENT,"category_uri" TEXT NOT NULL,"category_name" TEXT NOT NULL,"category_show" TEXT NOT NULL DEFAULT 'yes',"urutan" INTEGER DEFAULT 0);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_category_category_uri" ON "tbl_category" ("category_uri");
CREATE TABLE IF NOT EXISTS "tbl_comment" ("comment_id" INTEGER PRIMARY KEY AUTOINCREMENT,"article_id" INTEGER NOT NULL,"comment_date" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,"comment_name" TEXT NOT NULL,"comment_fill" TEXT NOT NULL,"comment_status" INTEGER NOT NULL,"comment_reply" TEXT);
CREATE TABLE IF NOT EXISTS "tbl_contact" ("contact_id" INTEGER PRIMARY KEY AUTOINCREMENT,"contact_name" TEXT NOT NULL,"contact_email" TEXT NOT NULL,"contact_hp" TEXT NOT NULL,"contact_desc" TEXT NOT NULL,"contact_created_date" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "tbl_label" ("label_id" INTEGER PRIMARY KEY AUTOINCREMENT,"label_uri" TEXT NOT NULL,"label_name" TEXT NOT NULL,"label_show" TEXT NOT NULL DEFAULT 'no',"urutan" INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "tbl_menu" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"tipe" TEXT,"id_menu" INTEGER,"uri_menu" TEXT,"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_pertanyaan" ("pertanyaan_id" INTEGER PRIMARY KEY AUTOINCREMENT,"pertanyaan_date" TEXT NOT NULL,"pertanyaan_nama" TEXT NOT NULL,"pertanyaan_email" TEXT NOT NULL,"pertanyaan" TEXT NOT NULL,"pertanyaan_status" INTEGER NOT NULL,"pertanyaan_jawaban" TEXT);
CREATE TABLE IF NOT EXISTS "tbl_pilihan" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"article_id" INTEGER NOT NULL,"posisi" TEXT,"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_quotes" ("quote_id" INTEGER PRIMARY KEY AUTOINCREMENT,"quote_image" TEXT NOT NULL,"quote_status" INTEGER NOT NULL,"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_referensi" ("id" INTEGER PRIMARY KEY AUTOINCREMENT,"sumber" TEXT NOT NULL DEFAULT 'int',"article_ref" INTEGER,"article_id" INTEGER,"judul" TEXT,"link" TEXT,"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_settings" ("setting_id" INTEGER PRIMARY KEY AUTOINCREMENT,"setting_name" TEXT NOT NULL,"setting_content" TEXT NOT NULL,"setting_last_updated" TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,"tipe" TEXT DEFAULT 'info',"urutan" INTEGER);
CREATE TABLE IF NOT EXISTS "tbl_sub_category" ("sub_category_id" INTEGER PRIMARY KEY AUTOINCREMENT,"category_id" INTEGER NOT NULL,"sub_category_uri" TEXT NOT NULL,"sub_category_name" TEXT NOT NULL,"sub_category_show" TEXT NOT NULL DEFAULT 'yes',"create_date" TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_sub_category_sub_category_uri" ON "tbl_sub_category" ("sub_category_uri");
CREATE TABLE IF NOT EXISTS "tbl_user" ("user_id" INTEGER PRIMARY KEY AUTOINCREMENT,"user_name" TEXT NOT NULL,"user_email" TEXT NOT NULL,"user_password" TEXT NOT NULL,"user_last_login" TEXT,"user_level" TEXT);
CREATE UNIQUE INDEX IF NOT EXISTS "tbl_user_admin_email" ON "tbl_user" ("user_email");
